            analytical, numerical, error);
        println!("  Actual opacity: sigmoid({:.2}) = {:.4}", opacity_logit,
            sugar_rs::core::sigmoid(opacity_logit));

        assert!(error < TOLERANCE_RELAXED,
            "Single Gaussian opacity gradient error too large: {}", error);

