            UnitQuaternion::identity(),     // No rotation
            2.0,                            // Opacity (logit-space, sigmoid(2.0) ≈ 0.88)
            {
                let mut sh = [[0.0f32; 3]; 16];
                sh[0] = [1.0, 0.0, 0.0]; // Red (in SH space)
