            UnitQuaternion::identity(),
            -1.0,  // Low opacity (sigmoid(-1.0) ≈ 0.27)
            {
                let mut sh = [[0.0f32; 3]; 16];
                sh[0] = [1.0, 0.0, 0.0]; // Red
