                loss_minus += pixels_minus[i].x + pixels_minus[i].y + pixels_minus[i].z;
            }
            let numerical = (loss_plus - loss_minus) / (2.0 * EPSILON);

            let error = rel_err(analytical, numerical);
            println!("  Gaussian 2: analytical={:.6}, numerical={:.6}, rel_err={:.6}",
