            alpha1_logit,
            {
                let mut sh = [[0.0f32; 3]; 16];
                sh[0] = [1.0, 0.0, 0.0]; // Red
                sh
            },
        );

        // Gaussian 2: Pure green (far)
        let gaussian2 = Gaussian::new(
            Vector3::new(0.0, 0.0, 10.0),
            Vector3::new(-2.0, -2.0, -2.0),
            UnitQuaternion::identity(),
            alpha2_logit,
            {
                let mut sh = [[0.0f32; 3]; 16];
                sh[0] = [0.0, 1.0, 0.0]; // Green
                sh
            },
